      "rank": 1,
      "ballot_id": "B037",
      "proposed_laureates": [
        "Kazutoshi Mori",
        "Peter Walter"
      ],
      "assessment": {
        "nobel_worthiness": "The unfolded-protein response established a fundamental, conserved system for maintaining cellular proteostasis, with broad consequences for physiology and disease.",
        "attribution": "Mori and Walter provide a compact and well-defined attribution for complementary foundational discoveries of ER stress signaling.",
        "maturity": "The mechanism has been extensively corroborated over decades and has reshaped cell biology and disease research.",
        "uncertainties": [
          "The eventual clinical importance of particular UPR-directed interventions remains uneven across diseases."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Jens Juul Holst",
        "Daniel J. Drucker",
        "Svetlana Mojsov"
      ],
      "assessment": {
        "nobel_worthiness": "GLP-1 physiology enabled a major therapeutic transformation in diabetes and obesity while illuminating endocrine control of metabolism.",
        "attribution": "Holst, Drucker, and Mojsov represent key physiological, mechanistic, and peptide-identification contributions; translational credit is necessarily broader.",
        "maturity": "Clinical benefit and biological importance are now firmly established at exceptional scale.",
        "uncertainties": [
          "The discovery-to-drug-development chain includes additional important contributors not accommodated by a three-person award."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Ian H. Frazer",
        "Douglas R. Lowy",
        "John T. Schiller"
      ],
      "assessment": {
        "nobel_worthiness": "Virus-like-particle HPV vaccines made prevention of common virus-associated cancers a practical public-health achievement.",
        "attribution": "Frazer, Lowy, and Schiller are plausibly attributable to the decisive VLP vaccine concept and its experimental realization.",
        "maturity": "Large-scale effectiveness against infection, precancerous lesions, and cancer-related outcomes provides unusually mature confirmation.",
        "uncertainties": [
          "Population-level cancer outcomes depend on vaccine uptake and screening practices as well as vaccine biology."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Harold F. Dvorak",
        "Napoleone Ferrara",
        "Donald R. Senger"
      ],
      "assessment": {
        "nobel_worthiness": "VEGF biology and its inhibition established pathological angiogenesis as a tractable therapeutic target, especially in ophthalmic disease and cancer.",
        "attribution": "Dvorak, Ferrara, and Senger cover central discoveries linking vascular permeability, VEGF, and angiogenic disease biology.",
        "maturity": "The biological pathway and benefits of inhibition have been repeatedly validated in laboratory and clinical settings.",
        "uncertainties": [
          "Therapeutic effects and limitations differ substantially among disease settings."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B010",
      "proposed_laureates": [
        "D. Grahame Hardie"
      ],
      "assessment": {
        "nobel_worthiness": "AMPK revealed a central molecular logic by which cells detect energy stress and coordinate metabolism, growth, and adaptation.",
        "attribution": "Hardie is strongly associated with defining AMPK as an energy sensor, though the wider field includes important contributors.",
        "maturity": "Its core physiology has been robustly reproduced and integrated across diverse organisms and tissues.",
        "uncertainties": [
          "The extent to which individual human metabolic therapies act through AMPK is context-dependent."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Francis S. Collins",
        "John R. Riordan",
        "Lap-Chee Tsui"
      ],
      "assessment": {
        "nobel_worthiness": "Identification of CFTR provided a landmark demonstration of human disease-gene discovery and directly enabled mechanistic and therapeutic advances.",
        "attribution": "Collins, Riordan, and Tsui form a recognizable group for mapping, cloning, and molecular identification of CFTR.",
        "maturity": "The causal gene, channel biology, and ensuing clinical consequences have been settled for decades.",
        "uncertainties": [
          "The discovery was collaborative and its division of credit is more complex than three names convey."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B042",
      "proposed_laureates": [
        "Arthur L. Horwich",
        "F. Ulrich Hartl"
      ],
      "assessment": {
        "nobel_worthiness": "Chaperonin-assisted folding changed the understanding of how cells achieve productive protein folding and preserve proteome function.",
        "attribution": "Horwich and Hartl offer focused credit for the decisive genetic and biochemical elucidation of chaperonin-mediated folding.",
        "maturity": "The principle is deeply established and remains foundational to studies of proteostasis and protein-misfolding disease.",
        "uncertainties": [
          "The relationship between this broad mechanism and individual human disorders is not uniformly direct."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Jacques F. A. P. Miller"
      ],
      "assessment": {
        "nobel_worthiness": "The identification of distinct B- and T-lymphocyte lineages supplied a foundational framework for adaptive immunity.",
        "attribution": "Miller and Cooper are the named conceptual discoverers, but only Miller is proposed here because eligibility and attribution constraints require care.",
        "maturity": "The lineage distinction has been foundationally confirmed and underlies modern immunology and medicine.",
        "uncertainties": [
          "Eligibility and the inability to recognize every foundational contributor may constrain a present award."
        ]
      }
    }
  ]
